/**
 * A subject-scoped key such as `auth:login:<address>` takes the config of its
 * bucket (`auth:login`), so every address gets the same shape of limit.
 */
export function getBucketConfig(bucketKey: string): RateLimitConfig {
  const exact = RATE_LIMIT_BUCKETS[bucketKey];
  if (exact) return exact;

  const separator = bucketKey.lastIndexOf(":");
  const bucket =
    separator > 0 ? RATE_LIMIT_BUCKETS[bucketKey.slice(0, separator)] : undefined;
  return bucket ?? DEFAULT_BUCKET;
}

