export async function revokeSession(sessionId: SessionId): Promise<void> {
  getDb().delete(sessions).where(eq(sessions.id, sessionId)).run();
}

/** Removes the one session that owns this token hash; unknown hashes are a no-op. */
export async function revokeSessionByTokenHash(
  tokenHash: string,
): Promise<void> {
  getDb().delete(sessions).where(eq(sessions.tokenHash, tokenHash)).run();
}

/** Ends every session of one account and no other; returns how many it removed. */
export async function revokeUserSessions(userId: UserId): Promise<number> {
  const rows = getDb()
    .delete(sessions)
    .where(eq(sessions.userId, userId))
    .returning({ id: sessions.id })
    .all();
  return rows.length;
}

/**
 * Housekeeping sweep; returns how many rows it removed. Removes sessions whose
 * expiry has passed — those are already refused by `findSessionByTokenHash`.
 */
export async function purgeExpiredSessions(
  now: IsoTimestamp,
): Promise<number> {
  const rows = getDb()
    .delete(sessions)
    .where(lt(sessions.expiresAt, now))
    .returning({ id: sessions.id })
    .all();
  return rows.length;
}

