/**
 * Returns the token only while it is unused and unexpired.
 */
export async function findLiveResetToken(
  tokenHash: string,
): Promise<ResetToken | null> {
  const row = getDb()
    .select()
    .from(passwordResetTokens)
    .where(
      and(
        eq(passwordResetTokens.tokenHash, tokenHash),
        isNull(passwordResetTokens.usedAt),
        gt(passwordResetTokens.expiresAt, new Date().toISOString()),
      ),
    )
    .get();

  if (!row) return null;

  return {
    id: row.id,
    userId: brandId<UserId>(row.userId),
    expiresAt: toIsoTimestamp(row.expiresAt),
  };
}

/** Retires every unused link of one account, leaving other accounts' links alone. */
export async function retireResetTokens(userId: UserId): Promise<void> {
  const stamp = toIsoTimestamp(new Date());
  getDb()
    .update(passwordResetTokens)
    .set({ usedAt: stamp, updatedAt: stamp })
    .where(
      and(
        eq(passwordResetTokens.userId, userId),
        isNull(passwordResetTokens.usedAt),
      ),
    )
    .run();
}

/**
 * Single use: marks the token used only if it is still unused and unexpired.
 * Returns `false` when another request got there first, so a link can be
 * redeemed once even under concurrent submissions.
 */
export async function consumeResetToken(id: string): Promise<boolean> {
  const stamp = toIsoTimestamp(new Date());
  const rows = getDb()
    .update(passwordResetTokens)
    .set({ usedAt: stamp, updatedAt: stamp })
    .where(
      and(
        eq(passwordResetTokens.id, id),
        isNull(passwordResetTokens.usedAt),
        gt(passwordResetTokens.expiresAt, new Date().toISOString()),
      ),
    )
    .returning({ id: passwordResetTokens.id })
    .all();
  return rows.length > 0;
}

