/**
 * Consumes a reset token, rewrites the password hash and ends every session of
 * that account. The token is marked used before the new hash is written, so a
 * replay of the same link cannot overwrite a password the user has since
 * changed again. The token is 256 bits of randomness, so it is not rate limited
 * here — a limit keyed on the address would let one address block its owner's
 * reset.
 */
export async function confirmPasswordReset(
  input: PasswordResetConfirmInput,
): Promise<User> {
  const stored = await resetTokenRepo.findLiveResetToken(
    hashToken(input.token),
  );
  if (!stored) throw new Error(INVALID_RESET_LINK);

  const consumed = await resetTokenRepo.consumeResetToken(stored.id);
  if (!consumed) throw new Error(INVALID_RESET_LINK);

  await userRepo.updatePasswordHash(
    stored.userId,
    await hashPassword(input.password),
  );
  await sessionRepo.revokeUserSessions(stored.userId);

  const user = await userRepo.findUserById(stored.userId);
  if (!user) throw new Error(INVALID_RESET_LINK);

  return user;
}

