/**
 * `persistent` is false for a sign-in without "remember me": the cookie then
 * lasts only for the browser session, so it does not survive on a shared
 * computer. The server-side session still ends at its own `expiresAt`.
 */
export async function setSessionCookie(
  token: string,
  expiresAt: IsoTimestamp,
  persistent = true,
): Promise<void> {
  const jar = await cookies();
  jar.set(SESSION_COOKIE_NAME, token, {
    httpOnly: true,
    sameSite: "lax",
    secure: process.env.NODE_ENV === "production",
    path: "/",
    ...(persistent ? { expires: parseIso(expiresAt) } : {}),
  });
}

